import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1100;
const CX = W / 2;

const COLORS = {
  latent: { fill: '#ede7f6', stroke: '#4527a0' },
  time: { fill: '#fff3e0', stroke: '#e65100' },
  patch: { fill: '#e3f2fd', stroke: '#1976d2' },
  cond: { fill: '#fce4ec', stroke: '#c62828' },
  norm: { fill: '#e0f2f1', stroke: '#00897b' },
  attn: { fill: '#fce4ec', stroke: '#c62828' },
  mlp: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  gate: { fill: '#fff3e0', stroke: '#e65100' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_H = 80;
const SEQ_W = 200;
const STEP_GAP = 140;
const BOX_TO_ROW = 110;
const ROW_GAP = 120;
const WEIGHT_W = 140;
const WEIGHT_H = 80;
const SHAPE_GAP = 50;

// ═══════════════════════════════════════════════════════════════════════════════
// Helpers
// ═══════════════════════════════════════════════════════════════════════════════

interface DitStep extends StepInfo {}

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}
function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}
function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = 940
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 26).attr('cy', y + BOX_H / 2)
    .attr('r', 15).attr('fill', stroke);
  lbl(g, cx - w / 2 + 26, y + BOX_H / 2 + 1, String(sn), { size: 13, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 - 6, title, { size: 14, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 + 12, formula, { size: 10, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 30, 220);
  const h = 30;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 9, color, font: 'monospace' });
}

function seqMatrix(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = SEQ_W, h = MAT_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 5, dimTop: 'S', dimRight: 'D',
  });
}

function weightMat(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill = COLORS.weight.fill, stroke = COLORS.weight.stroke,
  w = WEIGHT_W, h = WEIGHT_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 5,
  });
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 18)
    .attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 14, weight: '700', color });
}

function smallOp(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 12)
    .attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '700', color });
}

function badgeRect(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string, w = 130, h = 32): void {
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '600', color: stroke });
}

function smallVec(g: Gsel, cx: number, cy: number, label: string, sub: string, fill: string, stroke: string, w = 100, h = 30): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 1,
  });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 120;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): DitStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function matmulRow(
  g: Gsel, cx: number, cy: number,
  inLabel: string, inSub: string, inFill: string, inStroke: string,
  wLabel: string, wSub: string, wFill: string, wStroke: string,
  outLabel: string, outSub: string, outFill: string, outStroke: string,
  inW = 170, wW = WEIGHT_W, outW = 170
): void {
  const gap = 44;
  const totalW = inW + gap + 36 + gap + wW + gap + 36 + gap + outW;
  let x = cx - totalW / 2;

  const inCx = x + inW / 2;
  seqMatrix(g, inCx, cy, inLabel, inSub, inFill, inStroke, inW, MAT_H);
  x += inW;

  const opX = x + gap / 2 + 18;
  opCircle(g, opX, cy, '×', inStroke);
  drawArrow(g as Sel, inCx + inW / 2 + 4, cy, opX - 20, cy, { color: inStroke });
  x += gap + 36;

  const wCx = x + wW / 2;
  weightMat(g, wCx, cy, wLabel, wSub, wFill, wStroke, wW, WEIGHT_H);
  drawArrow(g as Sel, opX + 20, cy, wCx - wW / 2 - 4, cy, { color: inStroke });
  x += wW;

  const eqX = x + gap / 2 + 18;
  lbl(g, eqX, cy, '=', { size: 14, weight: '700', color: '#64748b' });
  x += gap + 36;

  const outCx = x + outW / 2;
  seqMatrix(g, outCx, cy, outLabel, outSub, outFill, outStroke, outW, MAT_H);
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer — 6 steps
// ═══════════════════════════════════════════════════════════════════════════════

export function renderDiTArchitectureDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const nPatches = Number(params.n_patches) || 256;
  const dModel = Number(params.d_model) || 768;
  const nHeads = 12;
  const dHead = Math.floor(dModel / nHeads);
  const nBlocks = 28;
  const dFF = dModel * 4;

  const steps: DitStep[] = [];
  let stepId = 0;
  let y = 10;

  // Title
  lbl(g, CX, y + 14, 'DiT Architecture', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  lbl(g, CX, y + 8, 'Diffusion Transformer — predicts noise from latent patches and timestep', { size: 10, color: 'var(--text-muted)' });
  y += 30;

  y = paramSummary(g, CX, y, [
    `patches: ${nPatches}`, `d_model: ${dModel}`, `heads: ${nHeads} (d_h=${dHead})`,
    `blocks: ${nBlocks}`, `d_ff: ${dFF}`,
  ]);
  y += 32;

  // ── Step 1: Input Representations ────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Representations',
      `noisy latent: [${nPatches}, ${dModel}]   timestep: [${dModel}]`,
      COLORS.latent.fill, COLORS.latent.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    seqMatrix(gs, CX - 220, rowY, 'latent', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke);
    lbl(gs, CX - 220, rowY - MAT_H / 2 - 14, 'Noisy Latent Patches', { size: 10, color: COLORS.latent.stroke, weight: '600' });

    const tW = 130;
    drawMatrixBlock(gs as Sel, CX + 220 - tW / 2, rowY - 22, {
      width: tW, height: 44, label: 'timestep', sublabel: `[${dModel}]`,
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 6, rows: 2,
    });
    lbl(gs, CX + 220, rowY - 36, 'Timestep Embedding', { size: 10, color: COLORS.time.stroke, weight: '600' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 22,
      `latent z_t at noise level t;  timestep t encoded as sinusoidal + MLP → [${dModel}]`, COLORS.latent.stroke);

    steps.push(makeStep(stepId, 'Input', 'Input Representations',
      `latent [${nPatches}, ${dModel}], timestep [${dModel}]`,
      `Noisy latent patches from the VAE encoder at noise level t, plus a timestep embedding vector.`,
      'step-input', COLORS.latent.stroke, COLORS.latent.fill));
    y = rowY + MAT_H / 2 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 2: Patch Embedding (Linear Projection) ──────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-patch-embed', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Patch Embedding (Linear Projection)',
      `x = latent · W_embed + b  →  [${nPatches}, ${dModel}]`,
      COLORS.patch.fill, COLORS.patch.stroke);

    arrowDown(gs, CX - 220, y, hBottom, COLORS.latent.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    matmulRow(gs, CX, rowY,
      'latent', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke,
      'W_embed', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.patch.stroke,
      'x', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke,
      170, WEIGHT_W, 170);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `latent [${nPatches}, ${dModel}] · W_embed [${dModel}, ${dModel}] + b = x [${nPatches}, ${dModel}]`, COLORS.patch.stroke);

    steps.push(makeStep(stepId, 'Embed', 'Patch Embedding',
      `latent · W_embed → [${nPatches}, ${dModel}]`,
      'Linear projection maps noisy latent patches into the transformer\'s hidden dimension. Acts as the patch embedding layer.',
      'step-patch-embed', COLORS.patch.stroke, COLORS.patch.fill,
      [`x = latent @ W_embed + b_embed   # [${nPatches}, ${dModel}]`]));
    y = rowY + MAT_H / 2 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 3: Timestep Conditioning (AdaLN embedding) ──────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-timestep', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Timestep Conditioning (SiLU MLP)',
      `c = MLP(SiLU(timestep))  →  [${dModel}]  (generates scale γ, shift β, gate α)`,
      COLORS.time.fill, COLORS.time.stroke);

    arrowDown(gs, CX + 220, y, hBottom, COLORS.time.stroke);

    // Row 1: timestep → SiLU → W_t → c  (vertical layout for clarity)
    const rowY = hBottom + BOX_TO_ROW;
    const tW = 130;
    drawMatrixBlock(gs as Sel, CX - 320 - tW / 2, rowY - 22, {
      width: tW, height: 44, label: 'timestep', sublabel: `[${dModel}]`,
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 6, rows: 2,
    });
    lbl(gs, CX - 320, rowY - 36, 'Timestep', { size: 9, color: COLORS.time.stroke, weight: '600' });

    badgeRect(gs, CX - 160, rowY, 'SiLU', COLORS.time.fill, COLORS.time.stroke, 100, 34);
    drawArrow(gs as Sel, CX - 320 + tW / 2 + 4, rowY, CX - 160 - 50 - 4, rowY, { color: COLORS.time.stroke });

    weightMat(gs, CX + 10, rowY, 'W_t', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.time.stroke, 120, WEIGHT_H);
    drawArrow(gs as Sel, CX - 160 + 50 + 4, rowY, CX + 10 - 60 - 4, rowY, { color: COLORS.time.stroke });

    seqMatrix(gs, CX + 220, rowY, 'c', `[${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 120, MAT_H);
    drawArrow(gs as Sel, CX + 10 + 60 + 4, rowY, CX + 220 - 60 - 4, rowY, { color: COLORS.cond.stroke });
    lbl(gs, CX + 220, rowY - MAT_H / 2 - 14, 'Conditioning', { size: 9, color: COLORS.cond.stroke, weight: '600' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `c = SiLU(timestep) @ W_t + b  →  conditioning vector [${dModel}]`, COLORS.time.stroke);

    // Row 2: c projects to γ, β, α
    const paramY = rowY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP * 0.7;
    const labels = ['γ (scale)', 'β (shift)', 'α (gate)'];
    const fills = [COLORS.norm.fill, COLORS.norm.fill, COLORS.gate.fill];
    const strokes = [COLORS.norm.stroke, COLORS.norm.stroke, COLORS.gate.stroke];
    const paramW = 110;
    labels.forEach((lab, i) => {
      const px = CX - 180 + i * 180;
      drawMatrixBlock(gs as Sel, px - paramW / 2, paramY - 16, {
        width: paramW, height: 32, label: lab, sublabel: `[${dModel}]`,
        fill: fills[i], stroke: strokes[i], cols: 5, rows: 1,
      });
    });
    arrowDown(gs, CX + 220, rowY + MAT_H / 2, paramY - 22, COLORS.cond.stroke);
    lbl(gs, CX + 260, rowY + MAT_H / 2 + 24, 'projects to:', { size: 8, color: COLORS.cond.stroke, anchor: 'start' });

    shapeEq(gs, CX, paramY + 24,
      `c → γ, β (for AdaLN scale/shift) and α (for zero-init gating)`, COLORS.cond.stroke);

    steps.push(makeStep(stepId, 'Cond', 'Timestep Conditioning',
      `c = MLP(SiLU(t)) → γ, β, α`,
      `Timestep embedding produces conditioning vector c, which generates AdaLN parameters: scale (γ), shift (β), and gate (α).`,
      'step-timestep', COLORS.time.stroke, COLORS.time.fill,
      [`# Timestep conditioning via SiLU MLP`,
       `c = SiLU(timestep) @ W_t + b_t   # [${dModel}]`,
       `γ, β, α = project(c)           # scale, shift, gate`]));
    y = paramY + 24 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 4: AdaLN-Zero Normalization ─────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-adaln', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'AdaLN-Zero Normalization',
      `h = (1 + γ) · LayerNorm(x) + β   then   h = α ⊙ h  (zero-init gate)`,
      COLORS.norm.fill, COLORS.norm.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.patch.stroke);

    // Sub-row A: LayerNorm
    const lnRowY = hBottom + BOX_TO_ROW;
    seqMatrix(gs, CX - 280, lnRowY, 'x', `[${nPatches}, ${dModel}]`, COLORS.patch.fill, COLORS.patch.stroke, 160, MAT_H);
    badgeRect(gs, CX - 80, lnRowY, 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke, 150, 36);
    drawArrow(gs as Sel, CX - 280 + 80 + 4, lnRowY, CX - 80 - 75 - 4, lnRowY, { color: COLORS.norm.stroke });
    seqMatrix(gs, CX + 140, lnRowY, 'x_norm', `[${nPatches}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 170, MAT_H);
    drawArrow(gs as Sel, CX - 80 + 75 + 4, lnRowY, CX + 140 - 85 - 4, lnRowY, { color: COLORS.norm.stroke });

    shapeEq(gs, CX, lnRowY + MAT_H / 2 + 24,
      `x_norm = LayerNorm(x)  →  [${nPatches}, ${dModel}]`, COLORS.norm.stroke);

    // Sub-row B: Scale + Shift: (1+γ)·x_norm + β
    const scaleRowY = lnRowY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
    seqMatrix(gs, CX - 340, scaleRowY, 'x_norm', `[${nPatches}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 160, MAT_H);

    smallOp(gs, CX - 190, scaleRowY, '×', COLORS.norm.stroke);
    drawArrow(gs as Sel, CX - 340 + 80 + 4, scaleRowY, CX - 190 - 14, scaleRowY, { color: COLORS.norm.stroke });

    smallVec(gs, CX - 90, scaleRowY, '(1+γ)', `[${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 100, 32);
    drawArrow(gs as Sel, CX - 90 - 50 - 4, scaleRowY, CX - 190 + 14, scaleRowY, { color: COLORS.norm.stroke });

    smallOp(gs, CX + 30, scaleRowY, '+', COLORS.norm.stroke);
    drawArrow(gs as Sel, CX - 190 + 14, scaleRowY, CX + 30 - 14, scaleRowY, { color: COLORS.norm.stroke });

    smallVec(gs, CX + 130, scaleRowY, 'β', `[${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 80, 32);
    drawArrow(gs as Sel, CX + 130 - 40 - 4, scaleRowY, CX + 30 + 14, scaleRowY, { color: COLORS.norm.stroke });

    seqMatrix(gs, CX + 310, scaleRowY, 'h_scaled', `[${nPatches}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 180, MAT_H);
    drawArrow(gs as Sel, CX + 30 + 14, scaleRowY, CX + 310 - 90 - 4, scaleRowY, { color: COLORS.norm.stroke });

    shapeEq(gs, CX, scaleRowY + MAT_H / 2 + 24,
      `h_scaled = (1+γ) · x_norm + β  →  [${nPatches}, ${dModel}]  (adaptive scale & shift)`, COLORS.norm.stroke);

    // Sub-row C: Gate (α ⊙ h_scaled)
    const gateRowY = scaleRowY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
    seqMatrix(gs, CX - 220, gateRowY, 'h_scaled', `[${nPatches}, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 170, MAT_H);
    opCircle(gs, CX - 30, gateRowY, '⊙', COLORS.gate.stroke);
    drawArrow(gs as Sel, CX - 220 + 85 + 4, gateRowY, CX - 30 - 20, gateRowY, { color: COLORS.gate.stroke });

    smallVec(gs, CX + 100, gateRowY, 'α', `[${dModel}]`, COLORS.gate.fill, COLORS.gate.stroke, 80, 32);
    drawArrow(gs as Sel, CX + 100 - 40 - 4, gateRowY, CX - 30 + 20, gateRowY, { color: COLORS.gate.stroke });
    lbl(gs, CX - 30, gateRowY - 30, 'zero-init gate (α→0 at init)', { size: 8, color: COLORS.gate.stroke, weight: '600' });

    seqMatrix(gs, CX + 280, gateRowY, 'h', `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 160, MAT_H);
    drawArrow(gs as Sel, CX - 30 + 20, gateRowY, CX + 280 - 80 - 4, gateRowY, { color: COLORS.gate.stroke });

    shapeEq(gs, CX, gateRowY + MAT_H / 2 + 24,
      `h = α ⊙ h_scaled  →  [${nPatches}, ${dModel}]  (zero-init: α starts at 0, each block is identity at init)`, COLORS.gate.stroke);

    steps.push(makeStep(stepId, 'AdaLN', 'AdaLN-Zero Normalization',
      `h = α ⊙ ((1+γ)·LN(x) + β)`,
      'AdaLN-Zero: timestep-conditioned normalization with scale, shift, and a zero-initialized gate. Each DiT block starts as identity, enabling stable training of deep networks.',
      'step-adaln', COLORS.norm.stroke, COLORS.norm.fill,
      [`x_norm = LayerNorm(x)`,
       `h_scaled = (1 + γ) * x_norm + β   # adaptive scale & shift`,
       `h = α * h_scaled                  # zero-init gate (α→0 at init)`]));
    y = gateRowY + MAT_H / 2 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 5: DiT Transformer Block (Self-Attention + MLP) ─────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-transformer', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, `DiT Transformer Block (×${nBlocks})`,
      `h = h + Attn(AdaLN(h))  →  h = h + MLP(AdaLN(h))  (${nHeads} heads, d_ff=${dFF})`,
      COLORS.attn.fill, COLORS.attn.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.cond.stroke);

    // ─── Self-Attention Sub-layer ─────────────────────────────────────────
    const attnLabelY = hBottom + BOX_TO_ROW - 16;
    lbl(gs, CX, attnLabelY, '— Self-Attention Sub-layer —', { size: 11, weight: '700', color: COLORS.attn.stroke });

    // Row 1: QKV projection (vertical flow: h → W_qkv → Q,K,V)
    const qkvY = attnLabelY + 40 + MAT_H / 2;
    seqMatrix(gs, CX - 240, qkvY, 'h', `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 160, MAT_H);
    smallOp(gs, CX - 100, qkvY, '×', COLORS.attn.stroke);
    drawArrow(gs as Sel, CX - 240 + 80 + 4, qkvY, CX - 100 - 14, qkvY, { color: COLORS.attn.stroke });
    weightMat(gs, CX + 60, qkvY, 'W_qkv', `[${dModel}, ${dModel * 3}]`, COLORS.weight.fill, COLORS.attn.stroke, 140, WEIGHT_H);
    drawArrow(gs as Sel, CX - 100 + 14, qkvY, CX + 60 - 70 - 4, qkvY, { color: COLORS.attn.stroke });

    seqMatrix(gs, CX + 300, qkvY, 'Q,K,V', `[${nPatches}, ${dModel}×3]`, COLORS.attn.fill, COLORS.attn.stroke, 180, MAT_H);
    drawArrow(gs as Sel, CX + 60 + 70 + 4, qkvY, CX + 300 - 90 - 4, qkvY, { color: COLORS.attn.stroke });

    shapeEq(gs, CX, qkvY + MAT_H / 2 + 24,
      `Q,K,V = h · W_qkv  →  [${nPatches}, ${dModel}] each  (${nHeads} heads, d_head=${dHead})`, COLORS.attn.stroke);

    // Row 2: Attention score computation (explicit Q, K^T, scores, softmax)
    const scoreY = qkvY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
    lbl(gs, CX, scoreY - 24, 'Attention Score Computation', { size: 9, weight: '600', color: COLORS.attn.stroke });

    // Q · K^T / √d_head → scores
    smallVec(gs, CX - 350, scoreY, 'Q', `[B, h, S, d_h]`, COLORS.attn.fill, COLORS.attn.stroke, 120, 32);
    smallOp(gs, CX - 230, scoreY, '·', COLORS.attn.stroke);
    drawArrow(gs as Sel, CX - 350 + 60 + 4, scoreY, CX - 230 - 14, scoreY, { color: COLORS.attn.stroke });
    smallVec(gs, CX - 110, scoreY, 'K^T', `[B, h, d_h, S]`, COLORS.attn.fill, COLORS.attn.stroke, 120, 32);
    drawArrow(gs as Sel, CX - 110 - 60 - 4, scoreY, CX - 230 + 14, scoreY, { color: COLORS.attn.stroke });

    lbl(gs, CX + 10, scoreY, `/ √${dHead}`, { size: 10, weight: '600', color: COLORS.attn.stroke });

    badgeRect(gs, CX + 120, scoreY, 'softmax', '#fff8e1', '#f9a825', 100, 32);
    drawArrow(gs as Sel, CX + 30, scoreY, CX + 120 - 50 - 4, scoreY, { color: COLORS.attn.stroke });

    smallVec(gs, CX + 290, scoreY, 'A', `[B, h, S, S]`, COLORS.attn.fill, COLORS.attn.stroke, 140, 32);
    drawArrow(gs as Sel, CX + 120 + 50 + 4, scoreY, CX + 290 - 70 - 4, scoreY, { color: COLORS.attn.stroke });
    lbl(gs, CX + 290, scoreY - 24, 'attention weights', { size: 8, color: COLORS.attn.stroke });

    shapeEq(gs, CX, scoreY + 24 + SHAPE_GAP - 20,
      `A = softmax(Q · K^T / √${dHead})  →  [B, ${nHeads}, S, S]`, COLORS.attn.stroke);

    // Row 3: A @ V → attn_out
    const ctxY = scoreY + 24 + SHAPE_GAP + ROW_GAP * 0.5;
    smallVec(gs, CX - 200, ctxY, 'A', `[B, h, S, S]`, COLORS.attn.fill, COLORS.attn.stroke, 130, 32);
    smallOp(gs, CX - 80, ctxY, '·', COLORS.attn.stroke);
    drawArrow(gs as Sel, CX - 200 + 65 + 4, ctxY, CX - 80 - 14, ctxY, { color: COLORS.attn.stroke });
    smallVec(gs, CX + 40, ctxY, 'V', `[B, h, S, d_h]`, COLORS.attn.fill, COLORS.attn.stroke, 130, 32);
    drawArrow(gs as Sel, CX + 40 - 65 - 4, ctxY, CX - 80 + 14, ctxY, { color: COLORS.attn.stroke });

    seqMatrix(gs, CX + 240, ctxY, 'attn_out', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 170, MAT_H);
    drawArrow(gs as Sel, CX + 40 + 65 + 4, ctxY, CX + 240 - 85 - 4, ctxY, { color: COLORS.attn.stroke });

    shapeEq(gs, CX, ctxY + MAT_H / 2 + 24,
      `attn_out = A · V  →  [${nPatches}, ${dModel}]  (concatenate heads, reshape)`, COLORS.attn.stroke);

    // Row 4: Output projection
    const outProjY = ctxY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP * 0.6;
    matmulRow(gs, CX, outProjY,
      'attn_out', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke,
      'W_o', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.attn.stroke,
      'attn_proj', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke,
      170, 120, 170);

    shapeEq(gs, CX, outProjY + MAT_H / 2 + 24,
      `attn_proj = attn_out · W_o  →  [${nPatches}, ${dModel}]`, COLORS.attn.stroke);

    // Row 5: Residual add (attention)
    const resAttnY = outProjY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP * 0.7;
    seqMatrix(gs, CX - 200, resAttnY, 'attn_proj', `[${nPatches}, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 160, MAT_H);
    opCircle(gs, CX, resAttnY, '⊕', COLORS.out.stroke);
    drawArrow(gs as Sel, CX - 200 + 80 + 4, resAttnY, CX - 20, resAttnY, { color: COLORS.attn.stroke });

    seqMatrix(gs, CX + 200, resAttnY, 'h', `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 140, MAT_H);
    lbl(gs, CX + 200, resAttnY - MAT_H / 2 - 14, 'residual', { size: 9, color: COLORS.cond.stroke, weight: '600' });
    drawArrow(gs as Sel, CX + 200 - 70 - 4, resAttnY, CX + 20, resAttnY, { color: COLORS.cond.stroke });

    seqMatrix(gs, CX + 420, resAttnY, "h'", `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 140, MAT_H);
    drawArrow(gs as Sel, CX + 20, resAttnY, CX + 420 - 70 - 4, resAttnY, { color: COLORS.out.stroke });

    shapeEq(gs, CX, resAttnY + MAT_H / 2 + 24,
      `h' = h + attn_proj  →  [${nPatches}, ${dModel}]  (residual connection)`, COLORS.out.stroke);

    // ─── MLP Sub-layer ────────────────────────────────────────────────────
    const mlpLabelY = resAttnY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
    lbl(gs, CX, mlpLabelY, '— MLP Sub-layer (Feed-Forward) —', { size: 11, weight: '700', color: COLORS.mlp.stroke });

    // Row 6: h' → W_up → GELU → W_down → mlp_out
    const upY = mlpLabelY + 40 + MAT_H / 2;
    seqMatrix(gs, CX - 340, upY, "h'", `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 150, MAT_H);

    weightMat(gs, CX - 160, upY, 'W_up', `[${dModel}, ${dFF}]`, COLORS.weight.fill, COLORS.mlp.stroke, 130, WEIGHT_H);
    drawArrow(gs as Sel, CX - 340 + 75 + 4, upY, CX - 160 - 65 - 4, upY, { color: COLORS.mlp.stroke });
    smallOp(gs, CX - 260, upY, '×', COLORS.mlp.stroke);

    badgeRect(gs, CX + 20, upY, 'GELU', COLORS.mlp.fill, COLORS.mlp.stroke, 90, 34);
    drawArrow(gs as Sel, CX - 160 + 65 + 4, upY, CX + 20 - 45 - 4, upY, { color: COLORS.mlp.stroke });

    weightMat(gs, CX + 180, upY, 'W_down', `[${dFF}, ${dModel}]`, COLORS.weight.fill, COLORS.mlp.stroke, 130, WEIGHT_H);
    drawArrow(gs as Sel, CX + 20 + 45 + 4, upY, CX + 180 - 65 - 4, upY, { color: COLORS.mlp.stroke });

    seqMatrix(gs, CX + 370, upY, 'mlp_out', `[${nPatches}, ${dModel}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 170, MAT_H);
    drawArrow(gs as Sel, CX + 180 + 65 + 4, upY, CX + 370 - 85 - 4, upY, { color: COLORS.mlp.stroke });

    shapeEq(gs, CX, upY + MAT_H / 2 + 24,
      `mlp_out = GELU(h' · W_up) · W_down  →  [${nPatches}, ${dModel}]  (d_ff=${dFF})`, COLORS.mlp.stroke);

    // Row 7: Residual add (MLP)
    const resMlpY = upY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP * 0.7;
    seqMatrix(gs, CX - 200, resMlpY, 'mlp_out', `[${nPatches}, ${dModel}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 160, MAT_H);
    opCircle(gs, CX, resMlpY, '⊕', COLORS.out.stroke);
    drawArrow(gs as Sel, CX - 200 + 80 + 4, resMlpY, CX - 20, resMlpY, { color: COLORS.mlp.stroke });

    seqMatrix(gs, CX + 200, resMlpY, "h'", `[${nPatches}, ${dModel}]`, COLORS.cond.fill, COLORS.cond.stroke, 140, MAT_H);
    lbl(gs, CX + 200, resMlpY - MAT_H / 2 - 14, 'residual', { size: 9, color: COLORS.cond.stroke, weight: '600' });
    drawArrow(gs as Sel, CX + 200 - 70 - 4, resMlpY, CX + 20, resMlpY, { color: COLORS.cond.stroke });

    seqMatrix(gs, CX + 420, resMlpY, 'h_out', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 150, MAT_H);
    drawArrow(gs as Sel, CX + 20, resMlpY, CX + 420 - 75 - 4, resMlpY, { color: COLORS.out.stroke });

    shapeEq(gs, CX, resMlpY + MAT_H / 2 + 24,
      `h_out = h' + mlp_out  →  [${nPatches}, ${dModel}]  (×${nBlocks} blocks, each with AdaLN-Zero)`, COLORS.out.stroke);

    steps.push(makeStep(stepId, 'DiT', `DiT Block (×${nBlocks})`,
      `h + Attn(AdaLN(h)) + MLP(AdaLN(h))`,
      `${nBlocks} DiT transformer blocks with AdaLN-Zero conditioning. Self-attention + MLP with pre-norm and residual connections.`,
      'step-transformer', COLORS.attn.stroke, COLORS.attn.fill,
      [`# DiT Block (×${nBlocks}), each with AdaLN-Zero`,
       `γ, β, α = timestep_proj(t)`,
       `h_norm = α * ((1+γ) * LayerNorm(h) + β)`,
       `h = h + self_attention(h_norm)   # pre-norm + residual`,
       `h_norm2 = α * ((1+γ) * LayerNorm(h) + β)`,
       `h = h + MLP(h_norm2)             # pre-norm + residual`]));
    y = resMlpY + MAT_H / 2 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 6: Noise Prediction Output ──────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Noise Prediction Output (Linear Head)',
      `noise_pred = h_out · W_noise + b  →  [${nPatches}, ${dModel}]`,
      COLORS.out.fill, COLORS.out.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.out.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    matmulRow(gs, CX, rowY,
      'h_out', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke,
      'W_noise', `[${dModel}, ${dModel}]`, COLORS.weight.fill, COLORS.out.stroke,
      'noise_pred', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke,
      170, WEIGHT_W, 180);

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `noise_pred = h_out · W_noise + b  →  [${nPatches}, ${dModel}]  (predicted noise ε)`, COLORS.out.stroke);

    // Final output
    const finalY = rowY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
    arrowDown(gs, CX, rowY + MAT_H / 2, finalY - MAT_H / 2, COLORS.out.stroke);
    seqMatrix(gs, CX, finalY, 'ε_pred', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 240, MAT_H);
    lbl(gs, CX, finalY - MAT_H / 2 - 14, 'Predicted Noise', { size: 10, color: COLORS.out.stroke, weight: '600' });

    shapeEq(gs, CX, finalY + MAT_H / 2 + 24,
      `ε_pred [${nPatches}, ${dModel}] — used in diffusion sampling: z_{t-1} = f(z_t, ε_pred, t)`, COLORS.out.stroke);

    steps.push(makeStep(stepId, 'Output', 'Noise Prediction',
      `h_out · W_noise → ε_pred`,
      `Final linear projection predicts the noise added to the clean latent. Used during diffusion sampling to iteratively denoise.`,
      'step-output', COLORS.out.stroke, COLORS.out.fill,
      [`noise_pred = h_out @ W_noise + b   # [${nPatches}, ${dModel}]`,
       `# During sampling: z_{t-1} = denoise(z_t, noise_pred, t)`]));
    y = finalY + MAT_H / 2 + 24;
  }

  // ── Footer: Explanation + Component Links + Code ─────────────────────────
  y += 32;
  y = drawExplanation(g as Sel, CX - (W - 120) / 2, y, W - 120,
    'DiT (Diffusion Transformer) replaces U-Net with a pure transformer for diffusion models. ' +
    'AdaLN-Zero conditioning injects timestep information via adaptive normalization with zero-initialized gates, ' +
    `so each of the ${nBlocks} blocks starts as identity. This enables stable training of deep transformers for diffusion, ` +
    'achieving state-of-the-art FID scores (e.g., 2.7 on ImageNet 256×256 with 675M params).',
    'insight');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 120) / 2, y, (W - 120) / 2 - 8, 56, 'attention', 'Attention');
  drawComponentLink(g as Sel, CX + 8, y, (W - 120) / 2 - 8, 56, 'transformer-block', 'Transformer Block');
  y += 72;

  drawCodeAnnotation(g as Sel, CX - (W - 120) / 2, y, W - 120,
    'DiT Architecture — AdaLN-Zero (PyTorch)',
    [`Diffusion Transformer: ${nPatches} patches, d=${dModel}, ${nHeads}h, ${nBlocks} blocks`],
    [
      `class DiTBlock(nn.Module):`,
      `    def __init__(self, d_model=${dModel}, n_heads=${nHeads}):`,
      `        self.attn = MultiHeadAttention(${dModel}, ${nHeads})`,
      `        self.mlp = MLP(${dModel}, d_ff=${dFF})`,
      `        # AdaLN-Zero: zero-init gate for stable deep training`,
      ``,
      `    def adaln_zero(self, x, c):`,
      `        γ, β, α = self.cond_proj(c)  # scale, shift, gate`,
      `        h = (1 + γ) * LayerNorm(x) + β`,
      `        return α * h                   # α→0 at init`,
      ``,
      `    def forward(self, x, timestep_emb):`,
      `        x = x + self.attn(self.adaln_zero(x, timestep_emb))`,
      `        x = x + self.mlp(self.adaln_zero(x, timestep_emb))`,
      `        return x`,
      ``,
      `class DiT(nn.Module):`,
      `    def forward(self, z_t, t):`,
      `        x = self.patch_embed(z_t)      # [${nPatches}, ${dModel}]`,
      `        c = self.timestep_mlp(t)       # conditioning`,
      `        for block in self.blocks:      # ×${nBlocks}`,
      `            x = block(x, c)`,
      `        return self.noise_head(x)      # ε_pred [${nPatches}, ${dModel}]`,
    ]);

  return { width: W, height: y + 24, steps };
}
